window.kbPageData["views/entry/k-a621391c4f93c6c7"] = {"key":"entry/k-a621391c4f93c6c7","state":{"route":"entry/k-a621391c4f93c6c7"},"node":{"id":"k-a621391c4f93c6c7","mode":"k","title":"行政处罚的集体讨论与听证顺序","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["情节复杂或重大违法行为的行政处罚由行政机关负责人集体讨论决定"],"qs":["江苏 2023 B类 行测#17"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"按2019年有效的《行政处罚法》，对情节复杂或者重大违法行为给予较重处罚，由行政机关负责人集体讨论决定。依法举行听证的，负责人应在听证结束后审查听证材料，再集体讨论并作出处罚决定。","review":{"definition":"按2019年有效的《行政处罚法》，对情节复杂或者重大违法行为给予较重处罚，由行政机关负责人集体讨论决定。依法举行听证的，负责人应在听证结束后审查听证材料，再集体讨论并作出处罚决定。","explanation":"听证前可以研究拟处罚方案，但听证意见必须进入最终决定程序。与题中5月21日集体讨论、5月30日听证、6月18日作出处罚相吻合的淮安医疗广告案中，终审法院认定，区市场监管局未能证明听证后重新集体讨论即罚款30万元，程序违法，撤销了处罚。题库所列B项与该判决冲突，现有选项没有合乎题意的正确项。","references":[{"source":"web-e8eecec5f03b8474","location":"第三十八条第二款、第四十三条","quote":"听证结束后，行政机关依照本法第三十八条的规定，作出决定"},{"source":"web-db0ff5d5b8fb6520","location":"第五十四条","quote":"当事人陈述和申辩意见或者听证报告"},{"source":"web-cde30711fb270fec","location":"转载判决书，二审法院认为及判决主文","quote":"其听证程序后未经集体讨论决定作出处罚"}],"evidence":"对该公司的违法行为进行集体讨论，决定罚款30万元并举行听证","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2023 B类 行测#17":{"paper":"江苏 2023 B类 行测","n":17,"mod":"常识判断","src":["22262c34d18cd68fbee4.pdf",3],"asrc":["b08f2713d73015eac675.pdf",7],"card":"46c0d47c902fde44cdbb48f7","links":[{"id":"k-a621391c4f93c6c7","role":"直接考查","why":"参考答案据此认定本案在听证前进行集体讨论符合法律规定。"}]}},"terms":{},"references":{"web-e8eecec5f03b8474":{"name":"《中华人民共和国行政处罚法》（2019年适用文本）","url":"https://qhca.miit.gov.cn/zwgk/zcwj/flfg/art/2022/art_68cb9f81db24484e98a6449590b6075a.html"},"web-db0ff5d5b8fb6520":{"name":"《市场监督管理行政处罚程序暂行规定》（总局令第2号）","url":"https://www.samr.gov.cn/zfjcj/tzgg/art/2023/art_e43ea0bf701445e5b7dbf06d3a356dbe.html"},"web-cde30711fb270fec":{"name":"淮安市中级人民法院（2020）苏08行终127号行政判决书","url":"https://m.thepaper.cn/newsDetail_forward_10911756"}},"topics":[],"units":{"k-a621391c4f93c6c7":[["江苏 2023 B类 行测#17"]]}};
